from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
leftmotor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
rightmotor = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(leftmotor, rightmotor, 56, 114)
motor_3 = Motor(Port.C, Direction.COUNTERCLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
mission = 0
max_mission = 3
running = 0
targetAngle = 0
currentAngle = 0
error = 0
correction = 0
Kp = 2
distance = 0

def mydrivestraight(dist):
    global targetAngle, baseSpeed, currentAngle, error, correction
    drive_base.use_gyro(True)
    drive_base.reset(0, 0)
    targetAngle = 0
    baseSpeed = 500
    while not drive_base.distance() >= dist:
        currentAngle = drive_base.angle()
        error = targetAngle - currentAngle
        correction = Kp * error
        drive_base.drive(baseSpeed, correction)
    drive_base.straight(0)


# The main program starts here.
print('Hello, Pybricks!')
# Im using the gyro so it can be perfectly straight and not be in an angel.
drive_base.use_gyro(True)
drive_base.settings(straight_speed=350)
drive_base.settings(turn_rate=100)
mydrivestraight(209)
drive_base.turn(-90)
# Turn 90 degrees towards the mission model
mydrivestraight(210)
drive_base.settings(straight_speed=200)
mydrivestraight(30)
motor_3.run_angle(100, 96)
drive_base.straight(-240)
drive_base.turn(28)
mydrivestraight(680)
drive_base.turn(15)
drive_base.settings(straight_speed=800)
drive_base.settings(turn_rate=500)
drive_base.straight(-690, then=Stop.NONE)
drive_base.turn(60, then=Stop.NONE)
drive_base.straight(-270)
